<?php class PdfSimple{private array $paginas=[],$lineas=[];private int $y=800;function linea(string $t='',int $tam=10,bool $negrita=false):void{foreach(explode("\n",wordwrap($t,95,"\n",true)) as $l){if($this->y<55)$this->pagina();$this->lineas[]=[$l,$tam,$negrita,$this->y];$this->y-=($tam+6);}}function titulo(string $t):void{$this->linea($t,16,true);$this->linea();}private function pagina():void{if($this->lineas)$this->paginas[]=$this->lineas;$this->lineas=[];$this->y=800;}private function esc(string $s):string{$s=iconv('UTF-8','Windows-1252//TRANSLIT',$s);return str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$s);}function descargar(string $nombre):never{$this->pagina();$o=[1=>'<< /Type /Catalog /Pages 2 0 R >>',3=>'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',4=>'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>'];$kids=[];$n=5;foreach($this->paginas as $pg){$p=$n++;$c=$n++;$kids[]="$p 0 R";$st='';foreach($pg as [$t,$z,$b,$y]){$f=$b?'F2':'F1';$st.="BT /$f $z Tf 45 $y Td (".$this->esc($t).") Tj ET\n";}$o[$c]="<< /Length ".strlen($st)." >>\nstream\n$st\nendstream";$o[$p]="<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents $c 0 R >>";}$o[2]='<< /Type /Pages /Kids ['.implode(' ',$kids).'] /Count '.count($kids).' >>';ksort($o);$pdf="%PDF-1.4\n";$off=[0];foreach($o as $i=>$v){$off[$i]=strlen($pdf);$pdf.="$i 0 obj\n$v\nendobj\n";}$x=strlen($pdf);$m=max(array_keys($o));$pdf.="xref\n0 ".($m+1)."\n0000000000 65535 f \n";for($i=1;$i<=$m;$i++)$pdf.=sprintf('%010d 00000 n ', $off[$i]??0)."\n";$pdf.="trailer << /Size ".($m+1)." /Root 1 0 R >>\nstartxref\n$x\n%%EOF";header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.$nombre.'"');echo $pdf;exit;}}